# Controlled-length witness coverage audit (dc_10 Step 3), valid range c <= c0+2:
# delta_c(L) = min over primitive k of max over witnesses from cycles of length <= L of |chi_k(W^2)-1|.
def units(Q): return [a for a in range(Q) if a%3!=0]
def descend_tables(c, c0):
    Qc=3**c; PHI=2*3**(c-1); inv2=pow(2,-1,Qc)
    m=3**(c-1); F={}
    for x in units(m):
        t=(3*x+1)%Qc; row=[0]*(PHI+1); v=t
        for b in range(1,PHI+1): v=(v*inv2)%Qc; row[b]=v
        F[x]=row
    level=c-1
    while level>c0:
        mlo=3**(level-1); new=units(mlo)
        rho=(F[(new[0]+mlo)%(3**level)][1]*pow(F[new[0]][1],-1,Qc))%Qc
        Fn={}
        for xh in new:
            t=(3*xh+1); row=[0]*(PHI+1)
            for b in range(1,PHI+1):
                v=(t*pow(inv2,b,3**level))%(3**level)
                row[b]=(F[xh][b]*pow(rho,(v-(v%mlo))//mlo,Qc))%Qc
            Fn[xh]=row
        F=Fn; level-=1
    return F
import cmath, math
def delta(c, c0, Lmax):
    Qc=3**c; F=descend_tables(c,c0)
    Q0=3**c0; U0=units(Q0); phi0=len(U0)
    succ={}; 
    for x in U0:
        for b in range(1,phi0+1):
            succ[(x,b)]=((3*x+1)*pow(pow(2,b,Q0),-1,Q0))%Q0
    cycles=[]
    for x in U0:
        for b1 in range(1,phi0+1):
            v1=succ[(x,b1)]
            if v1==x: cycles.append([(x,b1)])
            if Lmax>=2:
                for b2 in range(1,phi0+1):
                    if succ[(v1,b2)]==x and v1>x: cycles.append([(x,b1),(v1,b2)])
    def prod(cy):
        p=1
        for e in cy: p=(p*F[e[0]][e[1]])%Qc
        return p
    P=[(prod(cy),len(cy)) for cy in cycles]
    Ws=set()
    for i in range(len(P)):
        for j in range(i+1,len(P)):
            (p1,l1),(p2,l2)=P[i],P[j]
            W=(pow(p1,l2,Qc)*pow(p2,-l1,Qc))%Qc; W2=(W*W)%Qc
            if W2!=1: Ws.add(W2)
    ordp=3**(c-1); dl={}; p=1
    for j in range(ordp): dl[p]=j; p=(p*4)%Qc
    ts=[dl[w] for w in Ws if w in dl]
    if not ts: return None,0
    dmin=None
    for k in range(1,ordp):
        if k%3==0: continue
        sep=max(abs(cmath.exp(2j*math.pi*k*t/ordp)-1) for t in ts)
        if dmin is None or sep<dmin: dmin=sep
    return dmin,len(ts)

